import { Request } from "../../request";
import { SinglePayload, PaginatedPayload } from "../../types/payload";
import { Payload } from "../../types/payload";
import { Params } from "../../types/params";
/**
 * Member admin methods, reached as `memberstack.members.*`. Wraps the `/members` API:
 * list, retrieve, create, update and delete members, and attach or remove free plans.
 *
 * Every method returns a promise. Failures reject with a `{ code, message }` object.
 */
export default class MemberMethods extends Request {
    private endpoint;
    constructor(secretKey: string, test?: boolean, baseUrl?: string);
    /**
     * Lists members, one page at a time.
     *
     * @param params - Optional paging controls
     * @param params.limit - Page size, 1 to 100. Defaults to 50.
     * @param params.after - The `endCursor` from the previous page, to fetch the next one
     * @param params.order - `"ASC"` or `"DESC"` by creation date
     * @returns `{ data, totalCount, endCursor, hasNextPage }`. `endCursor` is a number and
     *   is never null, even on the last page; check `hasNextPage` to know when to stop.
     *
     * @example Walk every page
     * ```typescript
     * let after: number | undefined;
     * do {
     *   const page = await memberstack.members.list({ limit: 100, after });
     *   for (const member of page.data) console.log(member.auth.email);
     *   after = page.hasNextPage ? page.endCursor : undefined;
     * } while (after !== undefined);
     * ```
     */
    list(params?: Params.ListMembers): Promise<PaginatedPayload<Payload.Transforms["Member"]>>;
    /**
     * Creates a member with an email and password.
     *
     * @param params - The new member
     * @param params.email - Login email. Must be unique within the app.
     * @param params.password - Initial password
     * @param params.plans - Free plans to attach at signup, as `[{ planId }]`. Paid plans
     *   cannot be attached here; use the `@memberstack/dom` checkout flow for those.
     * @param params.customFields - Custom field values keyed by field key
     * @param params.metaData - Free-form metadata object
     * @param params.json - Member JSON blob
     * @param params.loginRedirect - Path to send the member to after login
     * @returns `{ data: member }`
     *
     * @example
     * ```typescript
     * const { data: member } = await memberstack.members.create({
     *   email: 'jane@example.com',
     *   password: 'a-strong-password',
     *   plans: [{ planId: 'pln_...' }],
     *   customFields: { 'first-name': 'Jane' }
     * });
     * console.log(member.id); // "mem_..."
     * ```
     */
    create(params: Params.CreateMember): Promise<SinglePayload<Payload.Transforms["Member"]>>;
    /**
     * Retrieves one member by id or by email. Pass exactly one of the two.
     *
     * @param params - `{ id }` or `{ email }`
     * @returns `{ data: member }`, or `{ data: null }` when no member matches. Unlike the
     *   other methods this does not reject on a miss.
     *
     * @example By id
     * ```typescript
     * const { data: member } = await memberstack.members.retrieve({ id: 'mem_...' });
     * ```
     *
     * @example By email
     * ```typescript
     * const { data: member } = await memberstack.members.retrieve({ email: 'jane@example.com' });
     * if (!member) console.log('no such member');
     * ```
     */
    retrieve(params: Params.RetrieveMember): Promise<SinglePayload<Payload.Transforms["Member"]>>;
    /**
     * Updates a member. Only the fields you pass change.
     *
     * `customFields` and `metaData` are shallow-merged into the existing values; `json` is
     * replaced whole. Changing `email` does not send a verification email.
     *
     * @param params - `{ id, data }`
     * @param params.id - The member id (`mem_...`)
     * @param params.data - Fields to change: `email`, `verified`, `customFields`, `metaData`,
     *   `json`, `loginRedirect`, `profileImage`
     * @returns `{ data: member }` with the updated member
     *
     * @example
     * ```typescript
     * const { data: updated } = await memberstack.members.update({
     *   id: 'mem_...',
     *   data: { verified: true, customFields: { 'first-name': 'Janet' } }
     * });
     * ```
     */
    update(params: Params.UpdateMember): Promise<SinglePayload<Payload.Transforms["Member"]>>;
    /**
     * Deletes a member permanently.
     *
     * @param params - `{ id, data? }`
     * @param params.id - The member id (`mem_...`)
     * @param params.data.deleteStripeCustomer - Also delete the linked Stripe customer
     * @param params.data.cancelStripeSubscriptions - Also cancel the member's Stripe subscriptions
     * @returns `{ data: { id } }` with the deleted member's id
     *
     * @example
     * ```typescript
     * await memberstack.members.delete({
     *   id: 'mem_...',
     *   data: { cancelStripeSubscriptions: true }
     * });
     * ```
     */
    delete(params: Params.DeleteMember): Promise<SinglePayload<{
        id: string;
    }>>;
    /**
     * Attaches a free plan to a member.
     *
     * Free plans only. A paid plan needs a Stripe checkout, which only the
     * `@memberstack/dom` package can start.
     *
     * @param params - `{ id, data: { planId } }`
     * @param params.id - The member id (`mem_...`)
     * @param params.data.planId - The free plan id (`pln_...`)
     * @returns The string `"OK"`. This route answers with plain text, not a `{ data }` envelope.
     *
     * @example
     * ```typescript
     * await memberstack.members.addFreePlan({ id: 'mem_...', data: { planId: 'pln_...' } });
     * ```
     */
    addFreePlan(params: Params.AddFreePlan): Promise<string>;
    /**
     * Removes a free plan from a member.
     *
     * Free plans only. Paid plans are cancelled through Stripe, not through this call.
     *
     * @param params - `{ id, data: { planId } }`
     * @param params.id - The member id (`mem_...`)
     * @param params.data.planId - The free plan id (`pln_...`)
     * @returns The string `"OK"`. This route answers with plain text, not a `{ data }` envelope.
     *
     * @example
     * ```typescript
     * await memberstack.members.removeFreePlan({ id: 'mem_...', data: { planId: 'pln_...' } });
     * ```
     */
    removeFreePlan(params: Params.RemoveFreePlan): Promise<string>;
}
